      "channel": 1
    }
  },
  "alignment": {
    "model": "Qwen3-ForcedAligner-0.6B",
    "source": "independent_posthoc_forced_alignment"
  }
}

{
  "model": "Qwen3-TTS-12Hz-1.7B-Base",
  "input": {
    "text": "反馈主要是频率高和优惠条件不清。客户体验希望补上停止条件。那现在可以把六十分钟顺序排出来了。",
